// ============================================================
// PARSE FORM
// ============================================================
const form = $input.first().json;

const brandName = (form['Brand Name'] || '').trim();
if (!brandName) throw new Error('Brand Name is required.');

const sheetUrl = form['Data Sheet URL (Google Sheets)'] || '';
const sheetIdMatch = sheetUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
const sheetId = sheetIdMatch ? sheetIdMatch[1] : '';
if (!sheetId) throw new Error('Invalid Google Sheet URL.');

const now = new Date();
const y1ago = new Date(now);
y1ago.setFullYear(y1ago.getFullYear() - 1);

return [{ json: {
  _brand_name: brandName,
  _brand_key: brandName.toLowerCase(),
  _vat_rate: parseFloat(form['VAT Rate']) || 0.23,
  _default_margin: parseFloat(form['Default Margin']) || 0.10,
  _feed_url: (form['Feed URL (XML)'] || '').trim(),
  _sheet_id: sheetId,
  _date_from: (form['Date From (YYYY-MM-DD)'] || '').trim() || y1ago.toISOString().split('T')[0],
  _date_to: (form['Date To (YYYY-MM-DD)'] || '').trim() || now.toISOString().split('T')[0],
  _form_ga4_id: (form['GA4 Property ID (opcjonalne)'] || '').trim(),
  _form_meta_id: (form['Meta Account ID (opcjonalne)'] || '').trim()
} }];

// ============================================================
// BUILD CONFIG + BRAND PERSISTENCE
// ============================================================

const formData = $node['Parse Form'].json;

const HARDCODED = {
  'iiyama':      { ga4: '280127077',  meta: 'act_1438113836305522' },
  'bushido':     { ga4: '297192186',  meta: 'act_1930400651212132' },
  'koszulkowy':  { ga4: '270928705',  meta: 'act_1897121353740892' },
  'mindlink':    { ga4: '477769901',  meta: 'act_1578563932814949' }
};

const sheetBrands = $input.all().map(i => i.json);
const sheetMatch = sheetBrands.find(row =>
  (row.brand_name || '').toLowerCase().trim() === formData._brand_key
);

const hardcoded = HARDCODED[formData._brand_key];
const ga4Id = formData._form_ga4_id
           || (sheetMatch ? (sheetMatch.ga4_property_id || '') : '')
           || (hardcoded ? hardcoded.ga4 : '');
const metaId = formData._form_meta_id
            || (sheetMatch ? (sheetMatch.meta_account_id || '') : '')
            || (hardcoded ? hardcoded.meta : '');

if (!ga4Id) throw new Error(`GA4 Property ID missing for "${formData._brand_name}"`);
if (!metaId) throw new Error(`Meta Account ID missing for "${formData._brand_name}"`);

const isNewBrand = !hardcoded && !sheetMatch;

return [{ json: {
  BRAND: formData._brand_name,
  VAT_RATE: formData._vat_rate,
  DEFAULT_MARGIN: formData._default_margin,
  FEED_URL: formData._feed_url,
  SHEET_ID: formData._sheet_id,
  GA4_PROPERTY_ID: ga4Id,
  META_ACCOUNT_ID: metaId,
  DATE_FROM: formData._date_from,
  DATE_TO: formData._date_to,
  MSC_ALGO: { MIN_META_TRANS: 10, MIN_ORGANIC_SESSIONS: 300 },
  _is_new_brand: isNewBrand
} }];

// ============================================================
// MARGIN RESOLVER — GATE NODE
// ============================================================

const rules = $input.all().map(item => ({
  match_type:  (item.json.match_type  || '').toUpperCase().trim(),
  match_value: (item.json.match_value || '').trim(),
  margin_rate: parseFloat(item.json.margin_rate) || 0
}));

const validTypes = ['SKU_EXACT', 'CATEGORY_EXACT', 'KEYWORD'];
const validRules = rules.filter(r => validTypes.includes(r.match_type) && r.margin_rate > 0);

const config = $node['Build Config'].json;

return [{ json: {
  ...config,
  MARGIN_RULES: validRules,
  MARGIN_RULES_COUNT: validRules.length,
  _resolver_executed: true
} }];

// NORMALIZE FEED + MARGINS
// FIX: g: namespace fields use bracket notation (p['g:id'] not p.g_id)
const config = $node['Margin Resolver'].json;
const marginRules = config.MARGIN_RULES || [];
const defaultMargin = config.DEFAULT_MARGIN || 0.10;

function normalizeUrl(url) {
  if (!url) return '';
  let u = url.toLowerCase().replace(/^https?:\/\/(www\.)?/, '').split('?')[0].replace(/\/$/, '');
  return u;
}

function resolveMargin(feedId, feedCategory) {
  const id = (feedId || '').trim();
  const cat = (feedCategory || '').toLowerCase().trim();
  for (const rule of marginRules) {
    if (rule.match_type === 'SKU_EXACT' && id === rule.match_value) return rule.margin_rate;
    if (rule.match_type === 'CATEGORY_EXACT' && cat === rule.match_value.toLowerCase()) return rule.margin_rate;
    if (rule.match_type === 'KEYWORD' && cat.includes(rule.match_value.toLowerCase())) return rule.margin_rate;
  }
  return defaultMargin;
}

const feedData = $input.first().json;
let products = [];
if (feedData.rss?.channel?.item) products = [feedData.rss.channel.item].flat();
else if (feedData.feed?.entry) products = [feedData.feed.entry].flat();
else if (feedData.products?.product) products = [feedData.products.product].flat();

return products.map(p => {
  // XML g: namespace produces keys like 'g:id', 'g:title', etc.
  const id = p['g:id'] || p.g_id || p.id || '';
  const cat = p['g:product_type'] || p['g:google_product_category'] || p.product_type || p.google_product_category || '';
  const link = p['g:link'] || p.g_link || p.link || '';
  const priceRaw = p['g:price'] || p.g_price || p.price || '0';
  const title = p['g:title'] || p.g_title || p.title || '';
  const brand = p['g:brand'] || p.g_brand || p.brand || '';

  return { json: {
    feed_id: id,
    feed_title: title,
    feed_brand: brand,
    feed_price: parseFloat(String(priceRaw).replace(/[^0-9.]/g, '')) || 0,
    feed_category: cat,
    feed_link: link,
    norm_url_path: normalizeUrl(link).split('/').slice(1).join('/'),
    base_gross_margin: resolveMargin(id, cat)
  }};
});

// NORMALIZE GA4 LP
return $input.first().json.rows.map(row => {
  const lp = row.dimensionValues[0].value || '';
  return { json: {
    ga4_lp_url: lp,
    ga4_norm_path: lp.toLowerCase().replace(/^\/|\/$/g, '').split('?')[0], // Match feed path
    ga4_sessions: parseInt(row.metricValues[0].value),
    ga4_revenue: parseFloat(row.metricValues[1].value),
    ga4_trans: parseInt(row.metricValues[2].value)
  }};
});

// NORMALIZE GA4 ITEMS
return $input.first().json.rows.map(row => {
  return { json: {
    ga4_item_id: row.dimensionValues[0].value,
    ga4_item_views: parseInt(row.metricValues[0].value),
    ga4_item_rev: parseFloat(row.metricValues[1].value),
    ga4_item_purch: parseInt(row.metricValues[2].value)
  }};
});

// NORMALIZE META ADS
const data = $input.first().json.data || [];
return data.map(ad => {
  const getVal = (list, type) => {
    if (!list) return 0;
    const m = list.find(x => x.action_type === type);
    return m ? parseFloat(m.value) : 0;
  };
  const purch = getVal(ad.actions, 'offsite_conversion.fb_pixel_purchase') || getVal(ad.actions, 'purchase');
  const val = getVal(ad.action_values, 'offsite_conversion.fb_pixel_purchase') || getVal(ad.action_values, 'purchase');
  const spend = parseFloat(ad.spend || '0');

  return { json: {
    meta_ad_id: ad.ad_id,
    meta_ad_name: ad.ad_name,
    meta_spend: spend,
    meta_purch: purch,
    meta_rev: val,
    meta_roas: spend > 0 ? val / spend : 0
  }};
});

// ============================================================
// MERGER NODE — The Great Joiner
// Joins Feed + GA4 Items + GA4 LP + Meta Ads
// ============================================================

// 1. Get all inputs by referencing upstream node names
const feed = $('Normalize Feed + Margins').all().map(i => i.json);
let ga4items = [];
try { ga4items = $('Normalize GA4 Items').all().map(i => i.json); } catch(e) {}
let ga4lp = [];
try { ga4lp = $('Normalize GA4 LP').all().map(i => i.json); } catch(e) {}
let meta = [];
try { meta = $('Normalize Meta Ads').all().map(i => i.json); } catch(e) {}

// 2. Index lookups for speed
const ga4ItemsMap = new Map();
ga4items.forEach(i => ga4ItemsMap.set(i.ga4_item_id, i));

const ga4LpMap = new Map();
ga4lp.forEach(p => ga4LpMap.set(p.ga4_norm_path, p));

// 3. Join Waterfall (Left Join Feed)
const mergedFeed = feed.map(prod => {
  // JOIN 1: Feed + GA4 Items (ID match)
  const gItem = ga4ItemsMap.get(prod.feed_id) || {};

  // JOIN 2: + GA4 LP (Path match)
  const gLp = ga4LpMap.get(prod.norm_url_path) || {};
  if (gLp.ga4_norm_path) ga4LpMap.delete(prod.norm_url_path); // MARK AS CONSUMED

  // JOIN 3: + Meta Ads (Ad Name fuzzy match)
  // GUARD: skip fuzzy match if feed_id is empty (would match everything)
  const mAds = prod.feed_id ? meta.filter(a => (a.meta_ad_name || '').includes(prod.feed_id)) : [];
  const mAgg = {
    meta_spend: mAds.reduce((s, a) => s + (a.meta_spend || 0), 0),
    meta_purch: mAds.reduce((s, a) => s + (a.meta_purch || 0), 0),
    meta_rev: mAds.reduce((s, a) => s + (a.meta_rev || 0), 0)
  };

  // Consolidate
  return { json: {
    ...prod,
    ga4_views: gItem.ga4_item_views || 0,
    ga4_purchases: gItem.ga4_item_purch || 0,
    ga4_revenue: gItem.ga4_item_rev || 0,
    lp_sessions: gLp.ga4_sessions || 0,
    lp_revenue: gLp.ga4_revenue || 0,
    lp_trans: gLp.ga4_trans || 0,
    meta_spend: mAgg.meta_spend,
    meta_revenue: mAgg.meta_rev,
    meta_roas: mAgg.meta_spend > 0 ? mAgg.meta_rev / mAgg.meta_spend : 0,
    _has_ga4_item: !!gItem.ga4_item_id,
    _has_ga4_lp: !!gLp.ga4_lp_url,
    _has_meta: mAds.length > 0,
    _merge_source: 'FEED'
  }};
});

// 4. Ghost LPs (Remaining unmatched LPs)
// Often brand pages, category pages, or non-product landings
const ghostLPs = Array.from(ga4LpMap.values()).map(lp => ({
    json: {
        feed_id: 'LP_' + lp.ga4_norm_path.replace(/[^a-zA-Z0-9]/g, '_'),
        feed_title: 'Unmatched LP: ' + lp.ga4_lp_url,
        feed_price: 0,
        feed_category: 'Unmatched Landing Page',
        feed_link: 'https://' + lp.ga4_lp_url,
        norm_url_path: lp.ga4_norm_path,
        base_gross_margin: 0.10, // Safety margin
        // Stats
        ga4_views: 0, ga4_purchases: 0, ga4_revenue: 0,
        lp_sessions: lp.ga4_sessions,
        lp_revenue: lp.ga4_revenue,
        lp_trans: lp.ga4_trans,
        meta_spend: 0, meta_revenue: 0, meta_roas: 0,
        // Flags
        _has_ga4_item: false, _has_ga4_lp: true, _has_meta: false,
        _merge_source: 'LP_ONLY'
    }
}));

return [...mergedFeed, ...ghostLPs];

// SAVE NEW BRAND CONFIG
const config = $node['Margin Resolver'].json;
if (!config._is_new_brand) return [];
return [{ json: {
  brand_name: config.BRAND,
  ga4_property_id: config.GA4_PROPERTY_ID,
  meta_account_id: config.META_ACCOUNT_ID,
  vat_rate: config.VAT_RATE,
  default_margin: config.DEFAULT_MARGIN,
  feed_url: config.FEED_URL,
  created_at: new Date().toISOString()
} }];

// ============================================================
// MSC-ALGO CLASSIFIER v5.0 — Full Waterfall (Gold Standard)
// Matches Iiyama_Growth_Opportunities.csv column structure
// ============================================================
const config = $node['Margin Resolver'].json;
const VAT = config.VAT_RATE || 0.23;
const BRAND = config.BRAND || '';
const allItems = $input.all().map(i => i.json);

// ====== HELPER: Percentile 75 (values > 0 only) ======
function p75(arr) {
  const sorted = arr.filter(v => v > 0).sort((a,b) => a-b);
  if (!sorted.length) return 1;
  return sorted[Math.floor(sorted.length * 0.75)] || 1;
}

// ====== PRE-COMPUTE: Efficiency metrics for all items ======
const enriched = allItems.map(p => {
  const price = p.feed_price || 0;
  const margin = p.base_gross_margin || 0.10;
  const spend = p.meta_spend || 0;
  const metaRev = p.meta_revenue || 0;
  const metaPurch = p.meta_purch || 0;
  const ga4Views = p.ga4_views || 0;
  const ga4ItemRev = p.ga4_revenue || 0;
  const ga4Purch = p.ga4_purchases || 0;
  const sessions = p.lp_sessions || 0;
  const lpRev = p.lp_revenue || 0;
  const lpTrans = p.lp_trans || 0;
  const isProduct = p._merge_source !== 'LP_ONLY';

  // Financial calcs
  const netRev = metaRev / (1 + VAT);
  const gp = netRev * margin;
  const cp = gp - spend;
  const roas = spend > 0 ? metaRev / spend : 0;
  const be = margin > 0.01 ? (1 + VAT) / margin : 999;
  const sc = be * 1.2;
  const netPrice = price / (1 + VAT);
  const bidCap = netPrice * margin;
  const costCap = bidCap;  // Same as bid cap per spec

  // LP efficiency
  const lpNetRev = lpRev / (1 + VAT);
  const lpGP = lpNetRev * margin;
  const gpps = sessions > 0 ? lpGP / sessions : 0;
  const cr = sessions > 0 ? lpTrans / sessions : 0;
  const freq = lpTrans > 0 ? lpRev / (lpTrans * (price || 1)) : 0;

  // Item efficiency
  const itemNetRev = ga4ItemRev / (1 + VAT);
  const itemGP = itemNetRev * margin;
  const gppv = ga4Views > 0 ? itemGP / ga4Views : 0;
  const arpu = sessions > 0 ? lpRev / sessions : 0;
  const arpiv = ga4Views > 0 ? ga4ItemRev / ga4Views : 0;

  return { ...p, _e: { price, margin, spend, metaRev, metaPurch, ga4Views, ga4ItemRev, ga4Purch, sessions, lpRev, lpTrans, isProduct, netRev, gp, cp, roas, be, sc, netPrice, bidCap, costCap, gpps, cr, freq, gppv, arpu, arpiv } };
});

// ====== DYNAMIC P75 THRESHOLDS ======
const P75_VOL_META = p75(enriched.map(e => e._e.metaRev));
const P75_EFF_META = p75(enriched.filter(e => e._e.cp > 0).map(e => e._e.cp));
const P75_VOL_GA = p75(enriched.map(e => e._e.sessions));
const P75_EFF_GA = p75(enriched.filter(e => e._e.gpps > 0).map(e => e._e.gpps));
const P75_VOL_ITEM = p75(enriched.map(e => e._e.ga4Views));
const P75_EFF_ITEM = p75(enriched.filter(e => e._e.gppv > 0).map(e => e._e.gppv));

// Avg CR for MIN_ORGANIC_SESSIONS
const crVals = enriched.map(e => e._e.cr).filter(v => v > 0);
const avgCR = crVals.length > 0 ? crVals.reduce((a,b) => a+b, 0) / crVals.length : 0.01;
const MIN_SESSIONS = Math.min(Math.ceil(100 / avgCR), 2000);

// ====== PRICE CLUSTERING ======
// Group by margin rate, then cluster by price within each group
const marginGroups = {};
enriched.forEach(e => {
  const key = e._e.margin.toFixed(2);
  if (!marginGroups[key]) marginGroups[key] = [];
  marginGroups[key].push(e);
});

const clusterMap = new Map();  // feed_id -> { label, avg_margin }
Object.entries(marginGroups).forEach(([marginKey, items]) => {
  const sorted = items.filter(e => e._e.price > 0).sort((a,b) => b._e.price - a._e.price);
  if (!sorted.length) {
    items.forEach(e => clusterMap.set(e.feed_id, { label: 'Other', avg: parseFloat(marginKey) }));
    return;
  }
  let leader = sorted[0]._e.price;
  let cluster = [sorted[0]];
  const flush = (cl) => {
    const avgM = cl.reduce((s,e) => s + e._e.margin, 0) / cl.length;
    const lbl = 'TOP ' + Math.round(cl[0]._e.price) + ' PLN';
    cl.forEach(e => clusterMap.set(e.feed_id, { label: lbl, avg: avgM }));
  };
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i]._e.price >= leader / 1.5) {
      cluster.push(sorted[i]);
    } else {
      flush(cluster);
      leader = sorted[i]._e.price;
      cluster = [sorted[i]];
    }
  }
  flush(cluster);
  // Items with price=0 get 'Other'
  items.filter(e => e._e.price <= 0).forEach(e => clusterMap.set(e.feed_id, { label: 'Other', avg: parseFloat(marginKey) }));
});

// ====== GA4 CLASS (2x2 matrix: sessions x CR vs P75) ======
function ga4Class(sessions, cr) {
  const highVol = sessions >= P75_VOL_GA;
  const highEff = cr >= (avgCR * 1.5); // Above-average CR
  if (highVol && highEff) return 'Star';
  if (highVol && !highEff) return 'Cash Cow';
  if (!highVol && highEff) return 'Hidden Gem';
  return 'Slacker';
}

// ====== WATERFALL CLASSIFIER ======
return enriched.map(p => {
  const e = p._e;
  let priority = 8;
  let segment = 'IGNORE';
  let reason = 'Insufficient data';
  let isActionable = false;
  let actionType = 'IGNORE';
  let metaClass = 'No Ads';
  const FLAGS = [];

  // Meta class
  if (e.spend > 0) {
    metaClass = e.cp > 0 ? 'Profitable' : 'Unprofitable';
  }

  // GA4 class
  const ga4C = ga4Class(e.sessions, e.cr);

  // === PHASE 1: META ADS FILTER ===
  if (e.metaPurch >= 10 || (e.spend > 0 && e.metaPurch >= 3)) {
    if (e.cp > 0) {
      if (e.metaRev >= P75_VOL_META && e.cp >= P75_EFF_META) {
        priority = 1; segment = 'PROVEN_STAR';
        reason = 'High ad revenue + profit';
        isActionable = true; actionType = 'SCALE_SPEND';
      } else {
        priority = 2; segment = 'PROVEN_COW';
        reason = 'Profitable ads, moderate scale';
        isActionable = true; actionType = 'MAINTAIN_SPEND';
      }
    } else {
      FLAGS.push('META_LOSER');
    }
  }

  // === PHASE 2: GA4 LANDING PAGE FILTER (only if not already classified) ===
  if (priority === 8 && e.sessions >= MIN_SESSIONS) {
    const isHighVol = e.sessions >= P75_VOL_GA;
    const isHighEff = e.gpps >= P75_EFF_GA;

    if (isHighVol && isHighEff) {
      priority = 3;
      segment = FLAGS.includes('META_LOSER') ? 'RECOVERY_LAUNCH' : 'NEW_STAR_LAUNCH';
      reason = 'High organic demand, untapped';
      isActionable = true; actionType = 'NEW_AD_CREATIVES';
    } else if (isHighVol && !isHighEff) {
      priority = 4; segment = 'FIX_LANDING_PAGE';
      reason = 'High traffic, low conversion';
      isActionable = true; actionType = 'UX_PRICE_AUDIT';
    } else if (!isHighVol && isHighEff) {
      priority = 5; segment = 'SCALE_UP';
      reason = 'Low traffic, high efficiency';
      isActionable = true; actionType = 'BROAD_CAMPAIGN';
    } else {
      FLAGS.push('LP_FAILURE');
    }
  }

  // === PHASE 3: GA4 ITEMS FILTER (only if still unclassified) ===
  if (priority === 8 && e.isProduct && e.ga4Views >= MIN_SESSIONS) {
    const isHighVol = e.ga4Views >= P75_VOL_ITEM;
    const isHighEff = e.gppv >= P75_EFF_ITEM;

    if (isHighVol && isHighEff) {
      priority = 6; segment = 'DIRECT_TO_PDP';
      reason = 'High PDP views + profit';
      isActionable = true; actionType = 'CONVERSION_CAMPAIGN';
    } else if (!isHighVol && isHighEff) {
      priority = 7; segment = 'FEED_DPA';
      reason = 'Profitable, low PDP visibility';
      isActionable = true; actionType = 'CATALOG_ADS_DPA';
    } else if (isHighVol && !isHighEff) {
      priority = 8; segment = 'IGNORE';
      reason = 'High views, no purchases';
    }
  }

  // Default reason for IGNORE
  if (priority === 8 && reason === 'Insufficient data') {
    if (e.ga4Views > 0 && e.gppv > 0) reason = 'High views, no purchases';
  }

  // Price cluster lookup
  const cl = clusterMap.get(p.feed_id) || { label: 'Other', avg: e.margin };

  // Infer price for non-products (avg of cluster or brand)
  const isProduct = e.isProduct;
  const isPriceInferred = !isProduct;
  const displayPrice = e.price > 0 ? e.price : 0;

  return { json: {
    // Identity (Gold Standard columns)
    feed_id: p.feed_id || '',
    feed_title: p.feed_title || '',
    feed_brand: p.feed_brand || BRAND,
    feed_category: p.feed_category || '',
    calc_gross_price: displayPrice,
    is_product: isProduct,
    is_price_inferred: isPriceInferred,
    feed_link: p.feed_link || '',
    norm_url: p.norm_url_path || '',
    // Classification
    calc_priority: priority,
    calc_segment: segment,
    calc_reason: reason,
    calc_is_actionable: isActionable,
    calc_action_type: actionType, calc_entity_type: isProduct ? 'PRODUCT' : 'CATEGORY_OR_AD',
    meta_class: metaClass,
    ga4_class: ga4C,
    // Margin & Financials
    base_gross_margin: e.margin,
    calc_contribution_profit: e.cp,
    calc_price_cluster: cl.label,
    critical_roas: e.be,
    scaling_roas: e.sc,
    calc_break_even_roas: e.be,
    // Efficiency
    calc_gpps: e.gpps,
    calc_cr: e.cr,
    calc_frequency: e.freq,
    calc_gppv: e.gppv,
    arpu: e.arpu,
    arpiv: e.arpiv,
    // Meta Ads
    meta_spend: e.spend,
    meta_revenue: e.metaRev,
    meta_purchases: e.metaPurch,
    calc_roas: e.roas,
    // GA4 Landing Page
    ga4lp_sessions: e.sessions,
    ga4lp_revenue: e.lpRev,
    ga4lp_purchases: e.lpTrans,
    ga4lp_first_time_purchasers: 0,  // Not available in current pipeline
    // GA4 Items
    ga4item_views: e.ga4Views,
    ga4item_revenue: e.ga4ItemRev,
    // Price & Caps
    calc_net_price: e.netPrice,
    calc_bid_cap: e.bidCap,
    calc_cost_cap: e.costCap,
    cluster_avg_margin: cl.avg
  }};
});
